using System.Diagnostics;using System.Drawing;using System.Net;using System.Security.Cryptography;using System.Text;using System.Text.Json;using System.Runtime.InteropServices;using System.Windows.Forms;
namespace PCBridgeGuest;
public sealed class MainForm:Form{
 [DllImport("user32.dll")]static extern bool SetCursorPos(int X,int Y);
 [DllImport("user32.dll")]static extern void mouse_event(uint f,uint x,uint y,uint d,UIntPtr e);
 [DllImport("user32.dll")]static extern void keybd_event(byte k,byte s,uint f,UIntPtr e);
 const uint DN=2,UP=4,KUP=2;HttpListener? srv;TextBox tok=new(){Width=300},log=new(){Multiline=true,ScrollBars=ScrollBars.Vertical,Dock=DockStyle.Fill};Button go=new(){Text="Start agent"},halt=new(){Text="Stop"};
 public MainForm(){Text="PCBridge Guest Agent";Width=720;Height=480;var p=new FlowLayoutPanel{Dock=DockStyle.Top,Height=65,Padding=new Padding(8)};tok.Text=Convert.ToHexString(RandomNumberGenerator.GetBytes(24));p.Controls.Add(new Label{Text="Token",AutoSize=true});p.Controls.Add(tok);p.Controls.Add(go);p.Controls.Add(halt);Controls.Add(log);Controls.Add(p);go.Click+=async(_,__)=>await Start();halt.Click+=(_,__)=>Stop();Add("Agent stopped by default. Loopback only.");}
 void Add(string x){if(!IsDisposed)BeginInvoke(()=>log.AppendText(DateTime.Now.ToString("HH:mm:ss ")+x+"\r\n"));}
 async Task Start(){if(srv!=null)return;srv=new();srv.Prefixes.Add("http://127.0.0.1:8765/");try{srv.Start();go.Enabled=false;Add("Listening localhost:8765");while(srv.IsListening){HttpListenerContext c;try{c=await srv.GetContextAsync();}catch{break;}_=Task.Run(()=>Handle(c));}}catch(Exception e){Add(e.Message);Stop();}}
 void Stop(){try{srv?.Stop();srv?.Close();}catch{}srv=null;go.Enabled=true;Add("Stopped");}
 bool Eq(string a,string b){var x=Encoding.UTF8.GetBytes(a);var y=Encoding.UTF8.GetBytes(b);return x.Length==y.Length&&CryptographicOperations.FixedTimeEquals(x,y);}
 async Task Handle(HttpListenerContext c){try{if(c.Request.HttpMethod!="POST"){await Out(c,405,"POST only");return;}if(!Eq(c.Request.Headers["X-PCBridge-Token"]??"",tok.Text)){await Out(c,401,"Unauthorized");return;}using var sr=new StreamReader(c.Request.InputStream);using var j=JsonDocument.Parse(await sr.ReadToEndAsync());var r=j.RootElement;var a=r.GetProperty("action").GetString()??"";string s=a switch{"status"=>"online","screenshot"=>Shot(),"open_url"=>Url(r.GetProperty("url").GetString()??""),"open_folder"=>Folder(r.GetProperty("path").GetString()??""),"click"=>Click(r.GetProperty("x").GetInt32(),r.GetProperty("y").GetInt32()),"type"=>Type(r.GetProperty("text").GetString()??""),"key"=>Key(r.GetProperty("key").GetString()??""),"run_confirmed"=>Run(r.GetProperty("command").GetString()??""),_=>"unsupported"};Add(a);await Out(c,200,s);}catch(Exception e){await Out(c,400,e.Message);}}
 string Url(string u){if(!Uri.TryCreate(u,UriKind.Absolute,out var z)||(z.Scheme!="https"&&z.Scheme!="http"))throw new Exception("http(s) only");Process.Start(new ProcessStartInfo(z.ToString()){UseShellExecute=true});return "opened";}
 string Folder(string p){if(!Directory.Exists(p))throw new Exception("folder missing");Process.Start(new ProcessStartInfo("explorer.exe",p){UseShellExecute=true});return "opened";}
 string Shot(){var b=Screen.PrimaryScreen!.Bounds;using var m=new Bitmap(b.Width,b.Height);using(var g=Graphics.FromImage(m))g.CopyFromScreen(b.Location,Point.Empty,b.Size);var p=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Desktop),"PCBridge-screen.png");m.Save(p);return p;}
 string Click(int x,int y){if(x<0||y<0||x>=Screen.PrimaryScreen!.Bounds.Width||y>=Screen.PrimaryScreen.Bounds.Height)throw new Exception("out of bounds");SetCursorPos(x,y);mouse_event(DN,0,0,0,UIntPtr.Zero);mouse_event(UP,0,0,0,UIntPtr.Zero);return "clicked";}
 string Type(string s){if(s.Length>1000)throw new Exception("limit 1000 chars");SendKeys.SendWait(s);return "typed";}
 string Key(string s){var d=new Dictionary<string,byte>(StringComparer.OrdinalIgnoreCase){{"ENTER",13},{"ESC",27},{"TAB",9},{"SPACE",32},{"F10",121}};if(!d.TryGetValue(s,out var k))throw new Exception("key allowlist");keybd_event(k,0,0,UIntPtr.Zero);keybd_event(k,0,KUP,UIntPtr.Zero);return "key sent";}
 string Run(string s){if(MessageBox.Show(this,"Run PowerShell command?\n"+s,"Consent",MessageBoxButtons.YesNo,MessageBoxIcon.Warning)!=DialogResult.Yes)return "cancelled";if(s.Length>1000)throw new Exception("command too long");var p=Process.Start(new ProcessStartInfo("powershell.exe","-NoProfile -Command \""+s.Replace("\"","\\\"")+"\""){UseShellExecute=false,RedirectStandardOutput=true,RedirectStandardError=true,CreateNoWindow=true})!;var o=p.StandardOutput.ReadToEnd();var e=p.StandardError.ReadToEnd();p.WaitForExit(10000);return $"exit={p.ExitCode}\n{o}\n{e}";}
 async Task Out(HttpListenerContext c,int n,string s){try{var b=Encoding.UTF8.GetBytes(s);c.Response.StatusCode=n;c.Response.ContentType="text/plain; charset=utf-8";c.Response.ContentLength64=b.Length;await c.Response.OutputStream.WriteAsync(b);c.Response.Close();}catch{}}
 protected override void OnFormClosing(FormClosingEventArgs e){Stop();base.OnFormClosing(e);}
}